//! Std-only smoke run of the `cdr_unitree` libFuzzer target
//! (`fuzz/fuzz_targets/`): the same harness code (`fuzz/harness/cdr_unitree.rs`,
//! included by path) driven by the deterministic mutator in
//! `fuzz/harness/smoke.rs` over the committed seed corpus. See
//! `fuzz/README.md`. `ROBODR_FUZZ_ITERS` / `ROBODR_FUZZ_SECS` tune the run.
//!
//! The committed seeds are (re)generated by the `regenerate_seeds` test
//! below (run with `--ignored`), which builds one valid payload of every
//! Unitree kind with the test encoder, each prefixed with the harness
//! selector byte.

#[path = "common/mod.rs"]
mod common;

#[path = "../../../fuzz/harness/cdr_unitree.rs"]
mod cdr_unitree;
#[path = "../../../fuzz/harness/smoke.rs"]
mod smoke;

use std::path::PathBuf;

use common::Enc;
use robodr_cdr::Representation;

/// One valid payload of each kind, with its harness selector byte and a
/// file name. The selector only steers the legacy branch; the DDS / JSON
/// paths run on every input.
fn seeds() -> Vec<(&'static str, Vec<u8>)> {
    let rep = Representation::CdrLe;

    // go WirelessController: 4 float32 + uint16.
    let mut wc = Enc::new(rep);
    wc.structure(|e| {
        e.f32(0.5);
        e.f32(-0.5);
        e.f32(0.0);
        e.f32(0.0);
        e.u16(0x00ff);
    });

    // api Request: Move(0.3, 0, -0.2) on the sport service.
    let mut req = Enc::new(rep);
    req.structure(|e| {
        e.structure(|e| {
            e.structure(|e| {
                e.i64(1);
                e.i64(1008);
            });
            e.structure(|e| e.i64(0));
            e.structure(|e| {
                e.i32(0);
                e.byte(1);
            });
        });
        e.string(br#"{"x":0.3,"y":0,"z":-0.2}"#);
        e.octet_seq(&[]);
    });

    // A bare JSON object (fed to the JSON reader directly, no selector
    // meaning): SetVelocity-shaped.
    let json = br#"{"velocity":[0.3,0.0,-0.4],"duration":1.0}"#.to_vec();

    // A legacy HighCmd (packed, all zero but level byte): 129 bytes.
    let mut high = vec![0u8; 129];
    high[2] = 0xee;

    vec![
        ("seed-wireless.bin", with_sel(0, wc.finish())),
        ("seed-api-move.bin", with_sel(0, req.finish())),
        ("seed-json.bin", with_sel(0, json)),
        ("seed-legacy-highcmd.bin", with_sel(2, high)),
    ]
}

fn with_sel(sel: u8, mut payload: Vec<u8>) -> Vec<u8> {
    let mut v = vec![sel];
    v.append(&mut payload);
    v
}

fn corpus_dir() -> PathBuf {
    smoke::corpus_dir(env!("CARGO_MANIFEST_DIR"), "cdr_unitree")
}

#[test]
fn seeds_are_valid_inputs() {
    for (name, data) in seeds() {
        // Must not panic, and must hit the harness invariants.
        cdr_unitree::run(&data);
        assert!(data.len() > 1, "{name} too short");
    }
}

#[test]
fn cdr_unitree_smoke() {
    let seeds = smoke::corpus(env!("CARGO_MANIFEST_DIR"), "cdr_unitree");
    smoke::run("cdr_unitree", &seeds, 0xc0de_0001, &cdr_unitree::run);
}

/// Regenerates the committed seed corpus. Run with
/// `cargo test -p robodr-cdr --test fuzz_smoke -- --ignored regenerate_seeds`.
#[test]
#[ignore = "writes into fuzz/corpus; run manually to refresh seeds"]
fn regenerate_seeds() {
    let dir = corpus_dir();
    std::fs::create_dir_all(&dir).unwrap();
    for (name, data) in seeds() {
        std::fs::write(dir.join(name), &data).unwrap();
    }
}
